export const DID_YOU_KNOW = DID_YOU_KNOW_GROUPS.flatMap(g => g.items.map(i => i.text));
const STORAGE_KEY = 'sbb:dyk-index';
function _readStoredIndex() {
try {
const raw = localStorage.getItem(STORAGE_KEY);
const n = parseInt(raw, 10);
return Number.isInteger(n) ? n : -1;
} catch (_) {
return -1;
}
}
function _writeStoredIndex(idx) {
try { localStorage.setItem(STORAGE_KEY, String(idx)); } catch (_) {   }
}
export function getNextDykIndex() {
const total = DID_YOU_KNOW.length;
if (!total) return 0;
const last = _readStoredIndex();
const next = (last + 1 + total) % total;
_writeStoredIndex(next);
return next;
}
export function getCurrentDykIndex() {
const total = DID_YOU_KNOW.length;
if (!total) return 0;
const idx = _readStoredIndex();
return (idx >= 0 && idx < total) ? idx : 0;
}
